// Human Health and Disease - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'

export const HUMAN_HEALTH_DISEASE = [

  // ============ HEALTH AND DISEASE: BASIC CONCEPTS ============
  { id: 'hhd-1', type: 'mcq', question: 'The World Health Organization (WHO) defines health as:', options: ['Merely the absence of disease', 'A state of complete physical, mental and social well-being', 'Only the absence of infectious disease', 'A purely genetic condition, unaffected by environment'], correctIndex: 1, explanation: 'According to WHO, health is a state of complete physical, mental and social well-being, and not merely the absence of disease or infirmity.', difficulty: 'easy' },
  { id: 'hhd-2', type: 'mcq', question: 'Factors that can affect an individual\'s health include:', options: ['Genetic disorders only', 'Only infections caused by microbes', 'Genetic disorders, infections, lifestyle and environmental factors, taken together', 'Environmental factors alone, with no genetic component'], correctIndex: 2, explanation: 'Health is influenced by a combination of genetic disorders, infections, lifestyle choices (diet, exercise, habits) and environmental factors.', difficulty: 'medium' },
  { id: 'hhd-3', type: 'mcq', question: 'A disturbance in the normal functioning of the body, which can be caused by infectious or non-infectious agents, is referred to as:', options: ['Immunity', 'Disease', 'Health', 'Vaccination'], correctIndex: 1, explanation: 'Disease refers to a condition in which the normal functioning of one or more organs/systems of the body is adversely affected.', difficulty: 'easy' },
  { id: 'hhd-4', type: 'mcq', question: 'Diseases caused by disease-causing organisms (pathogens), which can be transmitted from an infected person to a healthy person, are called:', options: ['Congenital diseases', 'Infectious (communicable) diseases', 'Genetic diseases', 'Nutritional deficiency diseases'], correctIndex: 1, explanation: 'Infectious diseases are caused by pathogens (bacteria, viruses, fungi, protozoans, helminths) and can spread from an infected individual to others.', difficulty: 'easy' },
  { id: 'hhd-5', type: 'mcq', question: 'Diseases that do not spread from one infected person to another and are usually persistent or long-lasting are called:', options: ['Communicable diseases', 'Non-communicable diseases', 'Vector-borne diseases only', 'Airborne diseases only'], correctIndex: 1, explanation: 'Non-communicable diseases (e.g., cancer, cardiovascular diseases) do not spread from person to person and are typically long-lasting.', difficulty: 'easy' },

  // ============ COMMON INFECTIOUS DISEASES: BACTERIAL DISEASES ============
  { id: 'hhd-6', type: 'mcq', question: 'Typhoid fever, a common bacterial disease in humans, is caused by:', options: ['Salmonella typhi', 'Mycobacterium tuberculosis', 'Streptococcus pneumoniae', 'Vibrio cholerae'], correctIndex: 0, explanation: 'Typhoid fever is caused by the bacterium Salmonella typhi.', difficulty: 'easy' },
  { id: 'hhd-7', type: 'mcq', question: 'Typhoid fever is usually diagnosed using a specific serological test called the:', options: ['ELISA test', 'Widal test', 'PCR test only', 'Blood smear test'], correctIndex: 1, explanation: 'The Widal test is commonly used to diagnose typhoid fever based on the detection of antibodies against Salmonella antigens.', difficulty: 'medium' },
  { id: 'hhd-8', type: 'mcq', question: 'Typhoid fever typically causes sustained high fever (39° to 40°C), along with which other common symptoms?', options: ['Weakness, stomach pain, constipation, headache and loss of appetite', 'Skin rashes exclusively, without any fever', 'Only joint pain, with no gastrointestinal symptoms', 'Sudden loss of vision'], correctIndex: 0, explanation: 'Typhoid symptoms include sustained high fever, weakness, stomach pain, constipation, headache and loss of appetite; intestinal perforation may occur in severe cases.', difficulty: 'medium' },
  { id: 'hhd-9', type: 'mcq', question: 'Pneumonia, an infection that affects the alveoli (air sacs) of the lungs, can be caused by which bacterium in humans?', options: ['Streptococcus pneumoniae', 'Salmonella typhi', 'Mycobacterium leprae', 'Vibrio cholerae'], correctIndex: 0, explanation: 'Streptococcus pneumoniae is one of the bacteria that can cause pneumonia, infecting the alveoli of the lungs.', difficulty: 'medium' },
  { id: 'hhd-10', type: 'mcq', question: 'In pneumonia, the alveoli become filled with fluid, leading to which characteristic symptom related to breathing?', options: ['Severe difficulty in breathing', 'No effect on breathing at all', 'Only mild coughing, with no breathing difficulty', 'Complete cessation of breathing permanently'], correctIndex: 0, explanation: 'The accumulation of fluid in the alveoli during pneumonia leads to severe difficulty in breathing, along with other symptoms like fever, chills and cough.', difficulty: 'medium' },
  { id: 'hhd-11', type: 'mcq', question: 'The common bacterial infections such as pneumonia and typhoid are generally spread by which route(s)?', options: ['Air (droplets from cough/sneeze) for pneumonia, and contaminated food/water for typhoid', 'Only direct skin contact for both diseases', 'Only insect bites for both diseases', 'Only through blood transfusions'], correctIndex: 0, explanation: 'Pneumonia is commonly spread through air (droplets from an infected person coughing/sneezing), while typhoid spreads through contaminated food and water.', difficulty: 'medium' },
  { id: 'hhd-12', type: 'assertion', question: 'Assertion (A): The Widal test is a useful diagnostic tool for typhoid fever.\nReason (R): The Widal test detects the presence of antibodies produced by the host\'s immune system in response to Salmonella typhi infection, indicating exposure to the pathogen.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The detection of specific antibodies against Salmonella antigens correctly explains the diagnostic utility of the Widal test for typhoid.', difficulty: 'medium' },
  { id: 'hhd-13', type: 'count', question: 'Consider the following statements about bacterial diseases:\n1. Typhoid fever is caused by Salmonella typhi.\n2. Pneumonia can be caused by Streptococcus pneumoniae, infecting the alveoli of the lungs.\n3. The Widal test is used to diagnose pneumonia specifically, not typhoid.\n4. Typhoid can lead to intestinal perforation in severe cases.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — the Widal test is specifically used to diagnose typhoid, not pneumonia.', difficulty: 'medium' },

  // ============ COMMON INFECTIOUS DISEASES: VIRAL DISEASES ============
  { id: 'hhd-14', type: 'mcq', question: 'The common cold, one of the most frequent viral infections in humans, primarily affects which region of the body?', options: ['The nose and respiratory passage (but not the lungs)', 'Only the digestive system', 'Only the skin', 'Only the nervous system'], correctIndex: 0, explanation: 'The common cold is a viral infection of the nose and respiratory passage (but not the lungs), caused by a group of viruses called Rhinoviruses.', difficulty: 'easy' },
  { id: 'hhd-15', type: 'mcq', question: 'The common cold is typically caused by a group of viruses called:', options: ['Rhinoviruses', 'Retroviruses', 'Adenoviruses exclusively', 'Coronaviruses exclusively'], correctIndex: 0, explanation: 'The common cold is most commonly caused by a group of viruses known as Rhinoviruses.', difficulty: 'medium' },
  { id: 'hhd-16', type: 'mcq', question: 'Common symptoms of the common cold include:', options: ['Nasal congestion and discharge, sore throat, hoarseness, cough and headache', 'Only high fever, with no respiratory symptoms', 'Joint pain and swelling exclusively', 'Complete loss of hearing'], correctIndex: 0, explanation: 'Typical symptoms of the common cold include nasal congestion, nasal discharge, sore throat, hoarseness, cough, headache and sometimes tiredness.', difficulty: 'medium' },
  { id: 'hhd-17', type: 'mcq', question: 'The common cold is highly infectious mainly because the virus is expelled through:', options: ['Coughing and sneezing, spreading through the air or physical contact', 'Only through blood transfusions', 'Only through insect bites', 'Contaminated soil, but never through air'], correctIndex: 0, explanation: 'The infection typically spreads through droplets released during coughing and sneezing, or through contact with objects contaminated by an infected person.', difficulty: 'medium' },
  { id: 'hhd-18', type: 'mcq', question: 'The common cold generally lasts for how many days, being self-limiting in nature?', options: ['3-7 days', '30-60 days', '6 months', 'It lasts indefinitely without any resolution'], correctIndex: 0, explanation: 'The common cold usually lasts for 3-7 days and is generally self-limiting, as the body\'s immune system typically clears the infection without special treatment.', difficulty: 'medium' },
  { id: 'hhd-19', type: 'assertion', question: 'Assertion (A): Antibiotics are not effective in treating the common cold.\nReason (R): The common cold is caused by a virus (Rhinovirus), and antibiotics are specifically effective against bacteria, not viruses.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The viral nature of the common cold correctly explains why antibiotics, which target bacterial infections, are ineffective against it.', difficulty: 'medium' },
  { id: 'hhd-20', type: 'count', question: 'Consider the following statements about the common cold:\n1. It is caused by a group of viruses called Rhinoviruses.\n2. It primarily affects the lungs, not the upper respiratory tract.\n3. It spreads through droplets released during coughing and sneezing.\n4. It is generally self-limiting, resolving within about a week.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — the common cold primarily affects the nose and upper respiratory passage, not the lungs.', difficulty: 'medium' },

  // ============ COMMON INFECTIOUS DISEASES: PROTOZOAN DISEASES ============
  { id: 'hhd-21', type: 'mcq', question: 'Malaria, one of the most significant infectious diseases in India, is caused by protozoan parasites belonging to the genus:', options: ['Entamoeba', 'Plasmodium', 'Trypanosoma', 'Leishmania'], correctIndex: 1, explanation: 'Malaria is caused by protozoan parasites of the genus Plasmodium, transmitted through the bite of an infected female Anopheles mosquito.', difficulty: 'easy' },
  { id: 'hhd-22', type: 'mcq', question: 'Malaria is transmitted from an infected person to a healthy person through the bite of:', options: ['Female Anopheles mosquito', 'Male Anopheles mosquito', 'Female Aedes mosquito', 'Female Culex mosquito'], correctIndex: 0, explanation: 'The female Anopheles mosquito acts as the vector transmitting Plasmodium parasites and causing malaria.', difficulty: 'easy' },
  { id: 'hhd-23', type: 'mcq', question: 'Among the various species of Plasmodium, which one causes the most severe and often fatal form of malaria (malignant malaria)?', options: ['Plasmodium vivax', 'Plasmodium malariae', 'Plasmodium falciparum', 'Plasmodium ovale'], correctIndex: 2, explanation: 'Plasmodium falciparum causes the most serious, malignant type of malaria, which can be fatal if left untreated.', difficulty: 'medium' },
  { id: 'hhd-24', type: 'mcq', question: 'The classic recurring symptom of malaria — high fever recurring every three to four days — is directly caused by:', options: ['The rupture of infected red blood cells, releasing a toxic substance called haemozoin', 'Continuous release of parasites into the liver', 'Inflammation of the lungs', 'An allergic reaction to mosquito saliva alone'], correctIndex: 0, explanation: 'The recurring fever of malaria coincides with the rupture of RBCs and release of a toxic substance called haemozoin, which is responsible for the chill and high fever.', difficulty: 'medium' },
  { id: 'hhd-25', type: 'mcq', question: 'After a female Anopheles mosquito bites an infected person, the Plasmodium parasite enters the mosquito\'s body and eventually develops into infective forms; when the mosquito bites another person, these infective forms called ______ are injected, initiating the infection.', options: ['Sporozoites', 'Merozoites', 'Gametocytes', 'Trophozoites'], correctIndex: 0, explanation: 'Sporozoites are the infective form of Plasmodium injected into the human bloodstream by the bite of an infected female Anopheles mosquito.', difficulty: 'medium' },
  { id: 'hhd-26', type: 'mcq', question: 'Once inside the human body, Plasmodium sporozoites first multiply within cells of the:', options: ['Liver', 'Skin', 'Brain', 'Kidney'], correctIndex: 0, explanation: 'Sporozoites first enter and multiply within liver cells before infecting red blood cells (RBCs), where further multiplication occurs.', difficulty: 'medium' },
  { id: 'hhd-27', type: 'mcq', question: 'Amoebiasis (amoebic dysentery), another common protozoan disease in humans, is caused by:', options: ['Plasmodium vivax', 'Entamoeba histolytica', 'Trypanosoma cruzi', 'Giardia lamblia specifically named otherwise'], correctIndex: 1, explanation: 'Amoebiasis is caused by the protozoan parasite Entamoeba histolytica, which infects the large intestine.', difficulty: 'easy' },
  { id: 'hhd-28', type: 'mcq', question: 'Amoebiasis, caused by Entamoeba histolytica, primarily results in symptoms related to:', options: ['Abdominal pain, cramps, stools with excess mucus and blood clots', 'Only skin rashes, without gastrointestinal symptoms', 'Only headache, without any digestive symptoms', 'Loss of hearing exclusively'], correctIndex: 0, explanation: 'Amoebiasis presents with symptoms such as abdominal pain, cramps, stools with excess mucus and blood clots, and constipation in some cases.', difficulty: 'medium' },
  { id: 'hhd-29', type: 'mcq', question: 'Entamoeba histolytica, the causative agent of amoebiasis, is typically transmitted through:', options: ['Contaminated food and water, mainly through the faecal-oral route (often via houseflies)', 'Mosquito bites', 'Direct blood contact only', 'Airborne transmission'], correctIndex: 0, explanation: 'Amoebiasis is transmitted through contaminated food and water, with houseflies acting as a mechanical vector by carrying cysts of the parasite from faeces to food.', difficulty: 'medium' },
  { id: 'hhd-30', type: 'assertion', question: 'Assertion (A): Malaria caused by Plasmodium falciparum is considered more dangerous than that caused by other Plasmodium species.\nReason (R): Plasmodium falciparum infection can cause the capillaries of the brain to be blocked (cerebral malaria), which can be fatal.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The severe complication of cerebral malaria, specifically associated with P. falciparum infection, correctly explains why this species causes the most dangerous form of malaria.', difficulty: 'medium' },
  { id: 'hhd-31', type: 'assertion', question: 'Assertion (A): Houseflies play an important role in the transmission of amoebiasis.\nReason (R): Houseflies act as mechanical carriers, transporting cysts of Entamoeba histolytica from the faeces of an infected person to food or water, which is then ingested by a healthy person.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The mechanical transfer of cysts by houseflies from contaminated faecal matter to food correctly explains their role in transmitting amoebiasis.', difficulty: 'medium' },
  { id: 'hhd-32', type: 'count', question: 'Consider the following statements about protozoan diseases:\n1. Malaria is transmitted by the bite of a female Anopheles mosquito.\n2. Plasmodium falciparum causes the most severe form of malaria.\n3. Sporozoites are the infective form injected by the mosquito into humans.\n4. Amoebiasis is caused by Plasmodium vivax.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — amoebiasis is caused by Entamoeba histolytica, not Plasmodium vivax (which causes a form of malaria).', difficulty: 'medium' },
  { id: 'hhd-33', type: 'count', question: 'Consider the following statements about the malarial parasite life cycle:\n1. Sporozoites first infect liver cells after entering the human body.\n2. Merozoites released from liver cells infect red blood cells.\n3. Rupture of RBCs releases haemozoin, causing chills and fever.\n4. The entire life cycle of Plasmodium occurs exclusively within the human host, without requiring a mosquito.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — Plasmodium requires both a human host and a mosquito vector to complete its full life cycle.', difficulty: 'hard' },
  { id: 'hhd-34', type: 'matching', question: 'Match Column I (protozoan disease) with Column II (causative organism):\nColumn I: A. Malaria  B. Amoebiasis\nColumn II: i. Entamoeba histolytica  ii. Plasmodium species', options: ['A-ii, B-i', 'A-i, B-ii', 'Both A and B — Entamoeba histolytica', 'Both A and B — Plasmodium species'], correctIndex: 0, explanation: 'Malaria — Plasmodium species; Amoebiasis — Entamoeba histolytica.', difficulty: 'easy' },

  // ============ COMMON INFECTIOUS DISEASES: HELMINTHIC DISEASES ============
  { id: 'hhd-35', type: 'mcq', question: 'Ascariasis, a common helminthic (worm-caused) disease in humans, is caused by the roundworm:', options: ['Ascaris lumbricoides', 'Wuchereria bancrofti', 'Taenia solium', 'Ancylostoma duodenale'], correctIndex: 0, explanation: 'Ascariasis is caused by the intestinal roundworm Ascaris lumbricoides.', difficulty: 'easy' },
  { id: 'hhd-36', type: 'mcq', question: 'A common general symptom of intestinal helminthic infections, including ascariasis, is:', options: ['Internal bleeding, muscular pain, fever, anaemia and blockage of the intestinal passage', 'Complete loss of taste', 'Loss of hearing', 'No noticeable symptoms in any patient'], correctIndex: 0, explanation: 'Common symptoms of ascariasis and similar helminthic infections include internal bleeding, muscular pain, fever, anaemia, and, in severe cases, intestinal blockage.', difficulty: 'medium' },
  { id: 'hhd-37', type: 'mcq', question: 'Eggs of Ascaris lumbricoides are typically released along with the faeces of an infected person and contaminate:', options: ['Soil, water and plants, from where infection is acquired via ingestion', 'Only air, never soil or water', 'Only blood transfusions', 'Only through direct mosquito bites'], correctIndex: 0, explanation: 'Ascaris eggs are excreted with faeces and contaminate soil, water and plants, from where a healthy person can become infected by consuming contaminated food and water.', difficulty: 'medium' },
  { id: 'hhd-38', type: 'mcq', question: 'Elephantiasis (filariasis), a chronic inflammatory disease caused by filarial worms, results in the swelling of which body parts?', options: ['Lower limbs and, in males, the genital organs', 'Only the face and neck', 'Only internal organs, with no external symptoms', 'The eyes exclusively'], correctIndex: 0, explanation: 'Elephantiasis causes gross deformity, particularly seen as swelling of the lower limbs and, in males, of the genital organs.', difficulty: 'medium' },
  { id: 'hhd-39', type: 'mcq', question: 'Elephantiasis (filariasis) is caused by slender, thread-like filarial worms of which genus?', options: ['Wuchereria (W. bancrofti and W. malayi)', 'Ascaris', 'Taenia', 'Trichinella'], correctIndex: 0, explanation: 'Filariasis is caused by filarial worms belonging to the genus Wuchereria (W. bancrofti and W. malayi), which affect the lymphatic vessels.', difficulty: 'medium' },
  { id: 'hhd-40', type: 'mcq', question: 'The filarial worms causing elephantiasis chronically inflame which structures of the body?', options: ['Lymphatic vessels of the lower limbs', 'The stomach lining exclusively', 'The heart valves', 'The kidneys exclusively'], correctIndex: 0, explanation: 'The filarial worms live in the lymphatic vessels (especially of the lower limbs), causing chronic inflammation and characteristic swelling.', difficulty: 'medium' },
  { id: 'hhd-41', type: 'mcq', question: 'The disease elephantiasis (filariasis) is transmitted from an infected person to a healthy one by:', options: ['Mosquito bites', 'Ingestion of contaminated food/water', 'Direct skin contact only', 'Airborne transmission'], correctIndex: 0, explanation: 'Filariasis is transmitted through the bite of mosquitoes, which act as vectors carrying the filarial worm larvae.', difficulty: 'medium' },
  { id: 'hhd-42', type: 'assertion', question: 'Assertion (A): Ascariasis is a common infection, particularly in regions with poor sanitation.\nReason (R): Since Ascaris eggs are transmitted via contaminated food, water, or soil, inadequate sanitation and hygiene practices increase the risk of transmission.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The link between contamination-based transmission and poor sanitation correctly explains the higher prevalence of ascariasis in such settings.', difficulty: 'medium' },
  { id: 'hhd-43', type: 'count', question: 'Consider the following statements about helminthic diseases:\n1. Ascariasis is caused by the roundworm Ascaris lumbricoides.\n2. Elephantiasis is caused by filarial worms of the genus Wuchereria.\n3. Ascariasis is transmitted through mosquito bites.\n4. Filariasis primarily affects the lymphatic vessels.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — ascariasis is transmitted through contaminated food/water, not mosquito bites (which transmit filariasis).', difficulty: 'medium' },

  // ============ COMMON INFECTIOUS DISEASES: FUNGAL DISEASES ============
  { id: 'hhd-44', type: 'mcq', question: 'Ringworm, a common fungal disease of the skin, typically presents as:', options: ['Dry, scaly lesions on various body parts, accompanied by intense itching', 'Only internal organ inflammation, with no visible skin symptoms', 'Complete hair loss over the entire body', 'A single symptom of high fever only'], correctIndex: 0, explanation: 'Ringworm causes dry, scaly lesions on various body parts such as the skin, nails and scalp, with intense itching.', difficulty: 'easy' },
  { id: 'hhd-45', type: 'mcq', question: 'Ringworm infections are caused by fungi belonging to genera such as:', options: ['Trichophyton, Microsporum and Epidermophyton', 'Plasmodium and Entamoeba', 'Ascaris and Wuchereria', 'Salmonella and Vibrio'], correctIndex: 0, explanation: 'Ringworm is caused by a group of fungi belonging to the genera Trichophyton, Microsporum and Epidermophyton.', difficulty: 'medium' },
  { id: 'hhd-46', type: 'mcq', question: 'Ringworm infections are generally acquired from:', options: ['Soil, or by using clothes and towels of infected individuals', 'Only through mosquito bites', 'Only through consumption of contaminated food', 'Only through blood transfusion'], correctIndex: 0, explanation: 'Ringworm can be acquired from soil, or by using contaminated clothes and towels belonging to an infected person or animal.', difficulty: 'medium' },
  { id: 'hhd-47', type: 'mcq', question: 'The prevalence of ringworm infections is generally higher in individuals who:', options: ['Maintain excellent hygiene, wearing clean, dry clothes at all times', 'Are habituated to using common/shared towels, clothes and hot, humid conditions', 'Never sweat, regardless of climate', 'Live only in cold, dry climates'], correctIndex: 1, explanation: 'Ringworm infections are common in hot, humid climates and among those who share towels/clothes or maintain poor personal hygiene, promoting fungal growth.', difficulty: 'medium' },
  { id: 'hhd-48', type: 'assertion', question: 'Assertion (A): Fungal diseases like ringworm often spread through shared personal items.\nReason (R): Fungal spores can survive on fabric surfaces such as towels and clothes, allowing transmission through direct or indirect contact when these items are shared.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The ability of fungal spores to persist on shared fabric items correctly explains why sharing towels/clothes contributes to the spread of ringworm.', difficulty: 'medium' },
  { id: 'hhd-49', type: 'matching', question: 'Match Column I (disease) with Column II (causative agent type):\nColumn I: A. Typhoid  B. Common cold  C. Malaria  D. Ringworm\nColumn II: i. Fungus  ii. Bacteria  iii. Protozoan  iv. Virus', options: ['A-ii, B-iv, C-iii, D-i', 'A-i, B-ii, C-iv, D-iii', 'A-iv, B-i, C-ii, D-iii', 'A-ii, B-iii, C-iv, D-i'], correctIndex: 0, explanation: 'Typhoid — bacteria; Common cold — virus; Malaria — protozoan; Ringworm — fungus.', difficulty: 'medium' },
  { id: 'hhd-50', type: 'statement', question: 'Statement I: All infectious diseases discussed in this chapter (typhoid, common cold, malaria, ascariasis, ringworm) are caused by the same broad category of pathogen.\nStatement II: These diseases collectively involve pathogens from at least four distinct biological categories — bacteria, viruses, protozoans, helminths and fungi.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — these diseases are caused by diverse pathogen types. Statement II is correct, as it accurately reflects the range of pathogen categories covered.', difficulty: 'medium' },

  // ============ IMMUNITY: BASIC CONCEPTS ============
  { id: 'hhd-51', type: 'mcq', question: 'The overall ability of the body to defend itself against foreign disease-causing organisms and substances is called:', options: ['Immunity', 'Metabolism', 'Homeostasis only', 'Digestion'], correctIndex: 0, explanation: 'Immunity refers to the overall biological defence mechanisms of the body against foreign pathogens and substances.', difficulty: 'easy' },
  { id: 'hhd-52', type: 'mcq', question: 'Immunity in vertebrates can be broadly classified into two major types:', options: ['Innate immunity and acquired immunity', 'Physical immunity and chemical immunity only', 'Passive immunity and negative immunity', 'Congenital immunity and induced immunity, unrelated to innate/acquired'], correctIndex: 0, explanation: 'Immunity is broadly categorised into innate immunity (present from birth) and acquired immunity (developed after exposure to a specific pathogen).', difficulty: 'easy' },
  { id: 'hhd-53', type: 'mcq', question: 'Innate immunity, present in an individual from the time of birth, provides:', options: ['A highly specific, pathogen-tailored response, developed gradually over time', 'A non-specific type of defence, providing barriers against entry of foreign agents', 'Immunity only against previously encountered pathogens', 'No protection whatsoever until later childhood'], correctIndex: 1, explanation: 'Innate immunity is a non-specific type of defence present at birth, providing various barriers against entry of foreign agents into the body.', difficulty: 'medium' },
  { id: 'hhd-54', type: 'mcq', question: 'Innate immunity involves multiple types of barriers; which of the following is an example of a physical barrier?', options: ['Skin and mucus coating of the epithelium lining the respiratory, digestive and urogenital tracts', 'Interferons secreted by virus-infected cells', 'Acid in the stomach', 'Neutrophils and natural killer cells'], correctIndex: 0, explanation: 'The skin and mucus coating along internal tracts constitute the physical barriers of innate immunity, preventing entry of microbes.', difficulty: 'medium' },
  { id: 'hhd-55', type: 'mcq', question: 'Which of the following is an example of a physiological barrier of innate immunity?', options: ['Acid in the stomach and saliva in the mouth', 'The skin covering the body', 'Neutrophils in the blood', 'Antibodies produced during infection'], correctIndex: 0, explanation: 'Physiological barriers include acid in the stomach, saliva in the mouth, and tears from the eyes, all of which prevent microbial growth.', difficulty: 'medium' },
  { id: 'hhd-56', type: 'mcq', question: 'Which of the following is an example of a cellular barrier of innate immunity?', options: ['Certain white blood cells, such as macrophages and neutrophils, which phagocytose and destroy microbes', 'Skin', 'Mucus membranes', 'Antibodies'], correctIndex: 0, explanation: 'Cellular barriers include leucocytes such as neutrophils and macrophages, which phagocytose and destroy invading microorganisms.', difficulty: 'medium' },
  { id: 'hhd-57', type: 'mcq', question: 'Which of the following is an example of a cytokine barrier of innate immunity?', options: ['Interferons, secreted by virus-infected cells, which protect neighbouring cells from further viral infection', 'Skin, providing a mechanical barrier', 'Saliva, providing a chemical barrier', 'Neutrophils, providing a cellular barrier'], correctIndex: 0, explanation: 'Cytokine barriers involve virus-infected cells secreting interferons, which protect adjacent, uninfected cells from viral infection.', difficulty: 'medium' },
  { id: 'hhd-58', type: 'mcq', question: 'Acquired immunity, unlike innate immunity, is characterised by:', options: ['Being pathogen-specific and mediated by lymphocytes, and having "memory"', 'Being non-specific and present from birth', 'Involving physical barriers alone', 'Providing no long-term protection whatsoever'], correctIndex: 0, explanation: 'Acquired (adaptive) immunity is pathogen-specific, mediated by B and T lymphocytes, and involves immunological memory of prior exposures.', difficulty: 'medium' },
  { id: 'hhd-59', type: 'mcq', question: 'The characteristic feature of acquired immunity, wherein the body responds more effectively and rapidly to a pathogen it has previously encountered, is called:', options: ['Memory', 'Innate response', 'Passive tolerance', 'Physical barrier response'], correctIndex: 0, explanation: 'Immunological memory is a hallmark of acquired immunity, whereby a subsequent encounter with the same pathogen elicits a heightened, faster immune response.', difficulty: 'medium' },
  { id: 'hhd-60', type: 'mcq', question: 'When the body encounters a pathogen for the first time, it generates a relatively slow and low-intensity response called the:', options: ['Primary response', 'Secondary response', 'Passive response', 'Delayed innate response'], correctIndex: 0, explanation: 'The primary response, occurring on first exposure to a pathogen, is relatively low in intensity.', difficulty: 'medium' },
  { id: 'hhd-61', type: 'mcq', question: 'On subsequent encounters with the same pathogen, the body mounts a much stronger and faster response, called the:', options: ['Primary response', 'Secondary (anamnestic) response', 'A completely absent response', 'Innate response only'], correctIndex: 1, explanation: 'The secondary (anamnestic) response, occurring upon subsequent encounters, is intensified and faster due to immunological memory.', difficulty: 'medium' },
  { id: 'hhd-62', type: 'assertion', question: 'Assertion (A): Vaccination provides long-lasting protection against specific diseases.\nReason (R): Vaccination stimulates the body\'s acquired immune system to generate memory cells, allowing a faster and stronger secondary response upon future exposure to the actual pathogen.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The generation of memory cells through vaccination correctly explains how it confers long-lasting, specific protection against future infections.', difficulty: 'medium' },
  { id: 'hhd-63', type: 'count', question: 'Consider the following statements about immunity:\n1. Innate immunity is non-specific and present from birth.\n2. Acquired immunity involves immunological memory.\n3. Physical barriers, physiological barriers, cellular barriers and cytokine barriers are all components of innate immunity.\n4. The primary immune response is generally stronger and faster than the secondary response.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — the secondary response is generally stronger and faster than the primary response, not the other way around.', difficulty: 'medium' },
  { id: 'hhd-64', type: 'matching', question: 'Match Column I (innate immunity barrier type) with Column II (example):\nColumn I: A. Physical barrier  B. Physiological barrier  C. Cellular barrier  D. Cytokine barrier\nColumn II: i. Interferons  ii. Neutrophils and macrophages  iii. Stomach acid  iv. Skin and mucus', options: ['A-iv, B-iii, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-iv, C-i, D-ii', 'A-iv, B-i, C-iii, D-ii'], correctIndex: 0, explanation: 'Physical barrier — skin and mucus; Physiological barrier — stomach acid; Cellular barrier — neutrophils and macrophages; Cytokine barrier — interferons.', difficulty: 'medium' },

  // ============ HUMORAL AND CELL-MEDIATED IMMUNITY ============
  { id: 'hhd-65', type: 'mcq', question: 'Acquired immunity can be further divided into two types based on the type of response involved:', options: ['Humoral immunity and cell-mediated immunity', 'Active immunity and passive immunity only', 'Innate immunity and adaptive immunity', 'Local immunity and systemic immunity'], correctIndex: 0, explanation: 'Acquired immune responses are of two types: humoral immunity (mediated by antibodies) and cell-mediated immunity (mediated by T-lymphocytes).', difficulty: 'medium' },
  { id: 'hhd-66', type: 'mcq', question: 'Humoral immunity is mediated primarily by:', options: ['B-lymphocytes, which produce antibodies', 'T-lymphocytes, without antibody involvement', 'Neutrophils exclusively', 'Skin cells'], correctIndex: 0, explanation: 'Humoral immunity is mediated by B-lymphocytes, which produce antibodies in response to antigens.', difficulty: 'medium' },
  { id: 'hhd-67', type: 'mcq', question: 'Antibodies, the effector molecules of humoral immunity, are complex molecules belonging to which class of biomolecules?', options: ['Immunoglobulins (proteins)', 'Lipids', 'Carbohydrates', 'Nucleic acids'], correctIndex: 0, explanation: 'Antibodies are immunoglobulins, a class of proteins produced in response to antigens.', difficulty: 'easy' },
  { id: 'hhd-68', type: 'mcq', question: 'A typical antibody molecule is composed of four peptide chains — two identical light chains and two identical heavy chains — giving it a characteristic shape resembling the letter:', options: ['Y', 'X', 'H', 'T'], correctIndex: 0, explanation: 'An antibody molecule has a characteristic Y-shaped structure, formed by two light chains and two heavy chains.', difficulty: 'medium' },
  { id: 'hhd-69', type: 'mcq', question: 'The five major classes of antibodies (immunoglobulins) found in humans are:', options: ['IgA, IgM, IgE, IgG and IgD', 'IgP, IgQ, IgR, IgS and IgT', 'Only IgG, with no other classes', 'IgA, IgB, IgC, IgD and IgE'], correctIndex: 0, explanation: 'The five classes of immunoglobulins are IgA, IgM, IgE, IgG and IgD, each with distinct roles in the immune response.', difficulty: 'medium' },
  { id: 'hhd-70', type: 'mcq', question: 'Cell-mediated immunity is primarily mediated by:', options: ['T-lymphocytes', 'B-lymphocytes exclusively', 'Only physical barriers', 'Red blood cells'], correctIndex: 0, explanation: 'Cell-mediated immunity is mediated by T-lymphocytes, which directly attack infected cells, especially those infected by intracellular pathogens like viruses.', difficulty: 'medium' },
  { id: 'hhd-71', type: 'mcq', question: 'Cell-mediated immunity plays a particularly important role in defending against which type of pathogen?', options: ['Intracellular pathogens, such as viruses, replicating inside host cells', 'Only extracellular bacteria, never intracellular pathogens', 'Only fungal spores present outside the cell', 'Only pathogens that never enter host cells'], correctIndex: 0, explanation: 'Since cell-mediated immunity involves direct action against infected cells, it is particularly important for eliminating intracellular pathogens like viruses.', difficulty: 'medium' },
  { id: 'hhd-72', type: 'mcq', question: 'Cell-mediated immunity is important in the rejection of transplanted tissue, a phenomenon known as:', options: ['Graft rejection', 'Antibody-mediated agglutination', 'Passive tolerance', 'Innate protection'], correctIndex: 0, explanation: 'The immune system\'s recognition and rejection of transplanted (non-self) tissue, mediated primarily by T-cells, is called graft rejection.', difficulty: 'medium' },
  { id: 'hhd-73', type: 'assertion', question: 'Assertion (A): Both humoral and cell-mediated immunity are essential components of a fully functional acquired immune response.\nReason (R): Humoral immunity (antibody-based) is generally effective against extracellular pathogens and toxins, while cell-mediated immunity is essential for eliminating intracellular pathogens and infected cells.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The complementary roles of humoral (extracellular threats) and cell-mediated (intracellular threats) immunity correctly explain why both are essential.', difficulty: 'hard' },
  { id: 'hhd-74', type: 'count', question: 'Consider the following statements about humoral and cell-mediated immunity:\n1. Humoral immunity is mediated by antibodies produced by B-lymphocytes.\n2. Cell-mediated immunity is mediated by T-lymphocytes.\n3. Antibodies belong to a class of proteins called immunoglobulins.\n4. There are five major classes of antibodies in humans.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 3, explanation: 'All four statements correctly describe features of humoral and cell-mediated immunity, and the structure/classes of antibodies.', difficulty: 'medium' },
  { id: 'hhd-75', type: 'matching', question: 'Match Column I (immunity type) with Column II (mediator):\nColumn I: A. Humoral immunity  B. Cell-mediated immunity\nColumn II: i. T-lymphocytes  ii. B-lymphocytes and antibodies', options: ['A-ii, B-i', 'A-i, B-ii', 'Both A and B — T-lymphocytes', 'Both A and B — B-lymphocytes'], correctIndex: 0, explanation: 'Humoral immunity — mediated by B-lymphocytes and antibodies; Cell-mediated immunity — mediated by T-lymphocytes.', difficulty: 'medium' },

  // ============ ACTIVE AND PASSIVE IMMUNITY, VACCINATION ============
  { id: 'hhd-76', type: 'mcq', question: 'When the body itself produces antibodies in response to exposure to an antigen (either through natural infection or vaccination), the resulting immunity is called:', options: ['Passive immunity', 'Active immunity', 'Innate immunity only', 'No immunity at all'], correctIndex: 1, explanation: 'Active immunity is generated when the body itself produces antibodies in response to an antigen, whether through infection or vaccination.', difficulty: 'medium' },
  { id: 'hhd-77', type: 'mcq', question: 'When ready-made antibodies are directly given to a person to protect them against a disease, rather than the person\'s own body producing antibodies, this is called:', options: ['Active immunity', 'Passive immunity', 'Innate immunity', 'Autoimmunity'], correctIndex: 1, explanation: 'Passive immunity involves the direct provision of ready-made antibodies to the body, rather than antibody production by the individual\'s own immune system.', difficulty: 'medium' },
  { id: 'hhd-78', type: 'mcq', question: 'A classic example of naturally occurring passive immunity is the transfer of antibodies from mother to child through:', options: ['Colostrum (the first milk produced during early lactation)', 'The placenta only, and never through breast milk', 'Vaccination given to the child soon after birth', 'Direct transfer of the mother\'s B-lymphocytes'], correctIndex: 0, explanation: 'Colostrum, the antibody-rich milk produced in early lactation, provides passive immunity to the newborn.', difficulty: 'medium' },
  { id: 'hhd-79', type: 'mcq', question: 'The administration of preformed antibodies, such as antitoxins, to a person after exposure to a pathogen or toxin (e.g., snake venom), is an example of artificially induced:', options: ['Active immunity', 'Passive immunity', 'Cell-mediated immunity only', 'Innate immunity'], correctIndex: 1, explanation: 'The administration of antitoxins or antibody preparations (such as anti-snake venom serum) provides immediate, ready-made antibodies, constituting passive immunity.', difficulty: 'medium' },
  { id: 'hhd-80', type: 'mcq', question: 'Vaccination (immunisation) is based on the property of the immune system referred to as:', options: ['Memory', 'Physical barrier response', 'Passive tolerance', 'Innate non-specificity'], correctIndex: 0, explanation: 'Vaccination exploits the memory property of the immune system, priming the body to respond rapidly upon future exposure to the actual pathogen.', difficulty: 'medium' },
  { id: 'hhd-81', type: 'mcq', question: 'In vaccination, a preparation of antigenic proteins of a pathogen, or an inactivated/weakened pathogen, is introduced into the body; this exposure generates:', options: ['A primary response, along with the generation of memory cells', 'Only a secondary response immediately', 'No response of any kind', 'A response that eliminates the immune system\'s ability to respond further'], correctIndex: 0, explanation: 'Vaccination triggers a primary immune response and, importantly, generates memory B and T-cells, providing rapid protection upon future exposure to the same pathogen.', difficulty: 'medium' },
  { id: 'hhd-82', type: 'assertion', question: 'Assertion (A): Passive immunity provides only short-term protection.\nReason (R): Since passive immunity involves the direct transfer of preformed antibodies rather than active production by the recipient\'s own immune system, no memory cells are generated, and the transferred antibodies eventually degrade.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The absence of memory cell generation and eventual degradation of transferred antibodies correctly explains the short-term nature of passive immunity.', difficulty: 'hard' },
  { id: 'hhd-83', type: 'count', question: 'Consider the following statements about active and passive immunity:\n1. Active immunity involves the body\'s own production of antibodies.\n2. Passive immunity is generally longer-lasting than active immunity, since memory cells are involved.\n3. Colostrum provides passive immunity to a newborn.\n4. Vaccination is a form of artificially induced active immunity.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — passive immunity is generally short-lived, unlike active immunity, since it does not involve memory cell generation.', difficulty: 'medium' },
  { id: 'hhd-84', type: 'statement', question: 'Statement I: In active immunity, the body\'s own immune system is stimulated to produce a specific response.\nStatement II: In passive immunity, ready-made antibodies are introduced into the body from an external source.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements correctly define the fundamental distinction between active immunity (self-generated response) and passive immunity (externally supplied antibodies).', difficulty: 'easy' },
  { id: 'hhd-85', type: 'matching', question: 'Match Column I (type of immunity) with Column II (example):\nColumn I: A. Naturally acquired active immunity  B. Artificially acquired active immunity  C. Naturally acquired passive immunity  D. Artificially acquired passive immunity\nColumn II: i. Antitoxin injection after snake bite  ii. Antibodies via colostrum from mother to infant  iii. Vaccination  iv. Recovery from natural infection', options: ['A-iv, B-iii, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-iv, C-i, D-ii', 'A-iv, B-i, C-iii, D-ii'], correctIndex: 0, explanation: 'Naturally acquired active — recovery from infection; Artificially acquired active — vaccination; Naturally acquired passive — colostrum antibodies; Artificially acquired passive — antitoxin injection.', difficulty: 'hard' },

  // ============ ALLERGIES AND AUTOIMMUNITY ============
  { id: 'hhd-86', type: 'mcq', question: 'An exaggerated immune response of the body against certain environmental antigens, such as pollen or dust, is called:', options: ['An allergy', 'Autoimmunity', 'Vaccination response', 'Passive immunity'], correctIndex: 0, explanation: 'An allergy refers to an exaggerated immune response against certain antigens (allergens) present in the environment.', difficulty: 'easy' },
  { id: 'hhd-87', type: 'mcq', question: 'The antigens that cause an allergic reaction in the body are commonly referred to as:', options: ['Allergens', 'Interferons', 'Cytokines', 'Immunoglobulins'], correctIndex: 0, explanation: 'Substances (antigens) that trigger allergic reactions are called allergens.', difficulty: 'easy' },
  { id: 'hhd-88', type: 'mcq', question: 'Common symptoms of an allergic reaction include:', options: ['Sneezing, watery eyes, running nose and difficulty in breathing', 'Complete loss of consciousness in every case', 'Immediate death, with no other visible symptoms', 'No noticeable symptoms at all'], correctIndex: 0, explanation: 'Typical allergic symptoms include sneezing, watery eyes, running nose, and, in respiratory allergies, difficulty in breathing.', difficulty: 'medium' },
  { id: 'hhd-89', type: 'mcq', question: 'Allergic responses in the body are commonly mediated by which class of antibodies?', options: ['IgE', 'IgG', 'IgA', 'IgD'], correctIndex: 0, explanation: 'Allergic reactions in the body are usually mediated by IgE-type antibodies produced in response to allergens.', difficulty: 'medium' },
  { id: 'hhd-90', type: 'mcq', question: 'Drugs commonly used to provide relief from allergic symptoms include:', options: ['Antihistamines, adrenaline and steroids', 'Antibiotics only', 'Antifungal drugs only', 'Antiviral drugs only'], correctIndex: 0, explanation: 'Antihistamines, adrenaline and steroids are commonly administered to reduce and manage the symptoms of an allergic reaction.', difficulty: 'medium' },
  { id: 'hhd-91', type: 'assertion', question: 'Assertion (A): Allergic reactions can sometimes be life-threatening.\nReason (R): In severe allergic responses (e.g., anaphylaxis), the exaggerated immune reaction can cause dangerous drops in blood pressure and severe difficulty breathing, requiring emergency treatment.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The physiological consequences of severe allergic reactions, such as anaphylaxis, correctly explain why allergies can be life-threatening in certain cases.', difficulty: 'medium' },
  { id: 'hhd-92', type: 'count', question: 'Consider the following statements about allergies:\n1. An allergy is an exaggerated immune response against certain environmental antigens.\n2. Allergens are the substances that trigger allergic reactions.\n3. Allergic reactions are generally mediated by IgG antibodies exclusively, never IgE.\n4. Antihistamines are commonly used to manage allergic symptoms.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — allergic reactions are usually mediated by IgE antibodies, not IgG exclusively.', difficulty: 'medium' },

  // ============ AIDS (ACQUIRED IMMUNODEFICIENCY SYNDROME) ============
  { id: 'hhd-93', type: 'mcq', question: 'AIDS (Acquired Immunodeficiency Syndrome) is caused by infection with which virus?', options: ['Human Immunodeficiency Virus (HIV)', 'Rhinovirus', 'Hepatitis B virus exclusively', 'Herpes simplex virus'], correctIndex: 0, explanation: 'AIDS is caused by infection with the Human Immunodeficiency Virus (HIV).', difficulty: 'easy' },
  { id: 'hhd-94', type: 'mcq', question: 'HIV, the causative agent of AIDS, belongs to a group of viruses known as:', options: ['Retroviruses', 'Adenoviruses', 'Rhinoviruses', 'Bacteriophages'], correctIndex: 0, explanation: 'HIV is a retrovirus, meaning it carries RNA as its genetic material and uses the enzyme reverse transcriptase to synthesise DNA within the host cell.', difficulty: 'medium' },
  { id: 'hhd-95', type: 'mcq', question: 'HIV primarily infects and destroys which type of immune cells in the body?', options: ['Helper T-lymphocytes', 'Red blood cells', 'Skin cells', 'Neurons exclusively'], correctIndex: 0, explanation: 'HIV specifically targets and destroys helper T-lymphocytes (a subset of white blood cells), severely compromising the immune system.', difficulty: 'medium' },
  { id: 'hhd-96', type: 'mcq', question: 'As HIV progressively destroys helper T-lymphocytes, the infected individual becomes increasingly susceptible to:', options: ['Various opportunistic infections that a normal immune system would readily control', 'No health consequences whatsoever', 'Only skin allergies', 'Improved resistance to all other infections'], correctIndex: 0, explanation: 'The progressive decrease in helper T-lymphocyte numbers weakens the immune system, making the individual susceptible to opportunistic infections.', difficulty: 'medium' },
  { id: 'hhd-97', type: 'mcq', question: 'HIV can be transmitted through which of the following routes?', options: ['Sexual contact with an infected person, transfusion of contaminated blood, sharing infected needles, and from an infected mother to her child during pregnancy/delivery/breastfeeding', 'Casual contact such as shaking hands or hugging', 'Mosquito bites', 'Sharing food or utensils'], correctIndex: 0, explanation: 'HIV transmission occurs primarily through sexual contact, transfusion of contaminated blood/blood products, sharing infected needles, and mother-to-child transmission; it does not spread through casual contact.', difficulty: 'medium' },
  { id: 'hhd-98', type: 'mcq', question: 'The diagnostic test commonly used to detect HIV infection, based on the detection of viral proteins or antibodies, is called:', options: ['ELISA (Enzyme-Linked Immunosorbent Assay)', 'Widal test', 'PCR for detecting bacteria only', 'Blood smear examination for parasites'], correctIndex: 0, explanation: 'ELISA is commonly used to detect HIV infection, based on identifying viral antigens or the presence of specific antibodies against HIV.', difficulty: 'medium' },
  { id: 'hhd-99', type: 'assertion', question: 'Assertion (A): AIDS patients are highly susceptible to a wide range of infections that rarely cause serious illness in individuals with a healthy immune system.\nReason (R): HIV progressively destroys helper T-lymphocytes, which play a central coordinating role in both humoral and cell-mediated immune responses.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The central coordinating role of helper T-lymphocytes, and their destruction by HIV, correctly explains the increased susceptibility to opportunistic infections in AIDS patients.', difficulty: 'medium' },
  { id: 'hhd-100', type: 'count', question: 'Consider the following statements about HIV/AIDS:\n1. HIV is a retrovirus.\n2. HIV primarily targets and destroys helper T-lymphocytes.\n3. HIV can be transmitted through casual contact such as handshakes.\n4. ELISA is commonly used to test for HIV infection.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — HIV is not transmitted through casual contact such as handshakes or hugging.', difficulty: 'medium' },
  { id: 'hhd-101', type: 'statement', question: 'Statement I: HIV can be transmitted from an infected mother to her child during pregnancy, delivery or breastfeeding.\nStatement II: The transmission routes of HIV are identical to those of the common cold virus.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 2, explanation: 'Statement I is correct. Statement II is incorrect — HIV transmission routes are entirely different from those of the common cold, which spreads via respiratory droplets.', difficulty: 'medium' },

  // ============ CANCER ============
  { id: 'hhd-102', type: 'mcq', question: 'Cancer is a disease characterised by:', options: ['Uncontrolled and abnormal proliferation of cells, along with invasion of surrounding normal tissue', 'Normal, regulated cell division only', 'A complete absence of cell division', 'Excessive apoptosis (programmed cell death) of all body cells'], correctIndex: 0, explanation: 'Cancer is characterised by uncontrolled cell proliferation, invasion into surrounding tissues, and, in malignant cases, spread to distant sites.', difficulty: 'easy' },
  { id: 'hhd-103', type: 'mcq', question: 'A localised mass of abnormally proliferating cells, which may or may not spread to other parts of the body, is called a:', options: ['Tumour (neoplasm)', 'Antibody', 'Allergen', 'Vaccine'], correctIndex: 0, explanation: 'A tumour (neoplasm) is a mass formed due to uncontrolled cell proliferation, which may be benign or malignant.', difficulty: 'easy' },
  { id: 'hhd-104', type: 'mcq', question: 'Tumours that remain confined to their original location and do not spread (metastasise) to other parts of the body are called:', options: ['Benign tumours', 'Malignant tumours', 'Neoplastic emboli', 'Metastatic tumours'], correctIndex: 0, explanation: 'Benign tumours remain confined to their site of origin and generally do not spread to other body parts.', difficulty: 'medium' },
  { id: 'hhd-105', type: 'mcq', question: 'Tumours that are highly invasive, capable of spreading to distant sites of the body and causing serious harm, are called:', options: ['Benign tumours', 'Malignant tumours', 'Cystic tumours only', 'Fibrous tumours only'], correctIndex: 1, explanation: 'Malignant tumours consist of rapidly dividing cells that invade surrounding tissue and can spread to other body parts, characteristic of cancer.', difficulty: 'medium' },
  { id: 'hhd-106', type: 'mcq', question: 'The process by which cancerous cells travel from their site of origin via the blood or lymph, invading and colonising distant tissues, is called:', options: ['Metastasis', 'Apoptosis', 'Phagocytosis', 'Regeneration'], correctIndex: 0, explanation: 'Metastasis refers to the spread of cancer cells via blood or lymph to distant sites, where they form new (secondary) tumours.', difficulty: 'medium' },
  { id: 'hhd-107', type: 'mcq', question: 'Physical, chemical and biological agents that cause cancer are collectively called:', options: ['Antioxidants', 'Carcinogens', 'Vaccines', 'Interferons'], correctIndex: 1, explanation: 'Carcinogens are agents (physical, chemical or biological) that induce cancer by causing DNA damage or other cellular changes.', difficulty: 'easy' },
  { id: 'hhd-108', type: 'mcq', question: 'Physical carcinogens include which of the following examples?', options: ['Ionising radiation (e.g., X-rays, gamma rays) and ultraviolet radiation', 'Certain viruses only', 'Certain chemicals in tobacco only', 'Only genetic factors, unrelated to physical agents'], correctIndex: 0, explanation: 'Physical carcinogens include ionising and ultraviolet radiation, both of which can cause DNA damage leading to cancer.', difficulty: 'medium' },
  { id: 'hhd-109', type: 'mcq', question: 'Chemical carcinogens, which can induce cancer, include substances such as:', options: ['Chemicals present in tobacco smoke', 'Only water', 'Only sugars', 'Only proteins'], correctIndex: 0, explanation: 'Chemical carcinogens include various substances, such as those found in tobacco smoke, which can cause cellular changes leading to cancer.', difficulty: 'medium' },
  { id: 'hhd-110', type: 'mcq', question: 'Biological carcinogens capable of inducing cancer include certain types of:', options: ['Viruses (oncogenic viruses)', 'Only bacteria', 'Only fungi', 'Only helminths'], correctIndex: 0, explanation: 'Certain oncogenic viruses are known biological carcinogens, capable of triggering cellular transformations that lead to cancer.', difficulty: 'medium' },
  { id: 'hhd-111', type: 'mcq', question: 'Genes present in a normal cell, called proto-oncogenes, can be activated under certain conditions to become cancer-causing genes called:', options: ['Oncogenes', 'Tumour suppressor genes', 'Interferon genes', 'Cytokine genes'], correctIndex: 0, explanation: 'Proto-oncogenes, when activated under certain conditions (e.g., mutation), become oncogenes, which can induce cancerous transformation of cells.', difficulty: 'medium' },
  { id: 'hhd-112', type: 'mcq', question: 'Genes that normally regulate cell division and prevent uncontrolled cell proliferation, whose loss of function can contribute to cancer development, are called:', options: ['Oncogenes', 'Tumour suppressor genes', 'Interferon genes', 'Histone genes'], correctIndex: 1, explanation: 'Tumour suppressor genes normally regulate the cell cycle and prevent uncontrolled proliferation; their inactivation can contribute to cancer development.', difficulty: 'medium' },
  { id: 'hhd-113', type: 'mcq', question: 'Cancer detection and diagnosis often involves techniques such as biopsy and histopathological studies, which primarily involve:', options: ['Microscopic examination of a tissue sample', 'Only external observation of the body', 'Only blood pressure measurement', 'Only measuring body temperature'], correctIndex: 0, explanation: 'A biopsy involves removing a tissue sample for histopathological (microscopic) examination, helping confirm the presence and type of cancer.', difficulty: 'medium' },
  { id: 'hhd-114', type: 'mcq', question: 'Imaging techniques used in cancer diagnosis, which allow visualisation of internal tumours without invasive surgery, include:', options: ['Radiography (X-rays), CT scan and MRI', 'Only stethoscope examination', 'Only physical palpation', 'Only blood typing'], correctIndex: 0, explanation: 'Radiography, CT (Computed Tomography) scan and MRI (Magnetic Resonance Imaging) are commonly used imaging techniques for detecting tumours.', difficulty: 'medium' },
  { id: 'hhd-115', type: 'mcq', question: 'Molecular biology techniques used in cancer diagnosis, particularly useful in detecting genes associated with cancer, include:', options: ['Techniques for detecting specific tumour markers/genes', 'Only stethoscope examination', 'Only physical examination of the skin', 'Only blood pressure monitoring'], correctIndex: 0, explanation: 'Molecular biology techniques, including detection of specific tumour markers or mutated genes, are increasingly used to identify cancer at earlier and more precise levels.', difficulty: 'medium' },
  { id: 'hhd-116', type: 'mcq', question: 'The three main approaches commonly used in the treatment of cancer include:', options: ['Surgery, radiotherapy and chemotherapy', 'Only surgery, with no other treatments available', 'Only vaccination', 'Only dietary modification'], correctIndex: 0, explanation: 'Cancer treatment commonly involves surgery (removal of the tumour), radiotherapy (radiation) and chemotherapy (drugs), often used in combination.', difficulty: 'easy' },
  { id: 'hhd-117', type: 'mcq', question: 'Radiotherapy, a common cancer treatment, involves exposing the tumour to carefully controlled doses of:', options: ['Radiation, which damages the cancerous cells', 'Only saline water', 'Only heat, unrelated to radiation', 'Only cold treatment'], correctIndex: 0, explanation: 'Radiotherapy involves exposing tumour cells to carefully targeted radiation doses, which damage/destroy the rapidly dividing cancer cells.', difficulty: 'medium' },
  { id: 'hhd-118', type: 'mcq', question: 'Chemotherapy, another common cancer treatment approach, involves the use of:', options: ['Specific drugs that have a killing effect on proliferating cancer cells', 'Only radiation, without any drugs', 'Only dietary supplements', 'Only vaccination against the cancer'], correctIndex: 0, explanation: 'Chemotherapy uses drugs designed to target and kill rapidly dividing cancer cells, though it can also affect other rapidly dividing normal cells, causing side effects.', difficulty: 'medium' },
  { id: 'hhd-119', type: 'mcq', question: 'A relatively newer approach to cancer treatment, which involves stimulating the patient\'s own immune system to combat the cancerous cells, is called:', options: ['Immunotherapy', 'Radiotherapy', 'Chemotherapy', 'Surgery'], correctIndex: 0, explanation: 'Immunotherapy involves administering substances (such as certain interferons) to boost the patient\'s immune system to help fight cancer cells.', difficulty: 'medium' },
  { id: 'hhd-120', type: 'assertion', question: 'Assertion (A): Metastasis is a defining feature of malignant tumours, but not of benign tumours.\nReason (R): Malignant tumour cells acquire the ability to invade surrounding tissue and travel via blood or lymph to distant sites, forming secondary tumours, whereas benign tumour cells remain localised.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The invasive and disseminating nature of malignant tumour cells, in contrast to the localised nature of benign tumours, correctly explains why metastasis distinguishes malignant from benign tumours.', difficulty: 'medium' },
  { id: 'hhd-121', type: 'assertion', question: 'Assertion (A): Chemotherapy often causes significant side effects such as hair loss and nausea.\nReason (R): Chemotherapy drugs target rapidly dividing cells, and since some normal cells (like hair follicle cells and cells lining the digestive tract) also divide rapidly, they are also affected by the treatment.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The non-selective action of chemotherapy drugs on all rapidly dividing cells, including normal ones, correctly explains the common side effects observed.', difficulty: 'medium' },
  { id: 'hhd-122', type: 'count', question: 'Consider the following statements about cancer:\n1. Benign tumours typically remain confined to their site of origin.\n2. Malignant tumours have the capacity to metastasise to distant body parts.\n3. Proto-oncogenes are always cancer-causing, even in their normal, unaltered state.\n4. Carcinogens can be physical, chemical or biological agents.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — proto-oncogenes are normal genes that only become cancer-causing (oncogenes) upon activation/mutation, not in their normal state.', difficulty: 'hard' },
  { id: 'hhd-123', type: 'count', question: 'Consider the following cancer diagnosis and treatment techniques:\n1. Biopsy\n2. MRI\n3. Radiotherapy\n4. Chemotherapy\n5. Immunotherapy\nHow many of the above are primarily treatment approaches, rather than diagnostic techniques?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Radiotherapy, chemotherapy and immunotherapy are treatment approaches. Biopsy and MRI are primarily diagnostic techniques.', difficulty: 'medium' },
  { id: 'hhd-124', type: 'statement', question: 'Statement I: All tumours are cancerous and pose an immediate threat to health.\nStatement II: Benign tumours generally do not spread to other parts of the body and are typically less life-threatening than malignant tumours.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — not all tumours are cancerous; benign tumours are generally less dangerous. Statement II correctly describes the relatively lower risk associated with benign tumours.', difficulty: 'medium' },
  { id: 'hhd-125', type: 'matching', question: 'Match Column I (cancer-related term) with Column II (description):\nColumn I: A. Oncogene  B. Tumour suppressor gene  C. Metastasis  D. Carcinogen\nColumn II: i. Agent causing cancer  ii. Spread of cancer cells to distant sites  iii. Gene that normally regulates and prevents excessive cell division  iv. Activated cancer-causing gene', options: ['A-iv, B-iii, C-ii, D-i', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-iv, C-i, D-ii', 'A-iv, B-i, C-iii, D-ii'], correctIndex: 0, explanation: 'Oncogene — activated cancer-causing gene; Tumour suppressor gene — regulates cell division; Metastasis — spread of cancer cells; Carcinogen — agent causing cancer.', difficulty: 'medium' },

  // ============ DRUGS AND ALCOHOL ABUSE ============
  { id: 'hhd-126', type: 'mcq', question: 'The use of drugs for purposes other than their intended medical use, often leading to harmful physical and psychological effects, is referred to as:', options: ['Drug abuse', 'Vaccination', 'Immunisation', 'Homeostasis'], correctIndex: 0, explanation: 'Drug abuse refers to the use of certain chemicals for gaining pleasure, often with detrimental effects on the individual, and generally seen with drugs affecting the nervous system.', difficulty: 'easy' },
  { id: 'hhd-127', type: 'mcq', question: 'Drugs and alcohol commonly used for their effects on the nervous system act primarily by:', options: ['Interfering with biochemical processes in the body, particularly targeting the brain and spinal cord', 'Only affecting the digestive system, without any impact on the brain', 'Only enhancing muscle strength, without any neurological effect', 'Providing purely nutritional benefits'], correctIndex: 0, explanation: 'Commonly abused drugs and alcohol interfere with biochemical processes in the body, particularly affecting the central nervous system (brain and spinal cord).', difficulty: 'medium' },
  { id: 'hhd-128', type: 'mcq', question: 'Opioids, a class of commonly abused drugs, typically act on the body by:', options: ['Binding to specific opioid receptors present in the central nervous system and gastrointestinal tract', 'Only affecting the liver, without acting on the nervous system', 'Only reducing blood pressure, without any effect on receptors', 'Acting exclusively on skin cells'], correctIndex: 0, explanation: 'Opioids act by binding to specific opioid receptors present mainly in the central nervous system and gastrointestinal tract, resulting in a variety of effects.', difficulty: 'medium' },
  { id: 'hhd-129', type: 'mcq', question: 'Morphine and heroin, well-known opioids, are typically obtained from the latex of the plant:', options: ['Papaver somniferum (opium poppy)', 'Cannabis sativa', 'Erythroxylum coca', 'Atropa belladonna'], correctIndex: 0, explanation: 'Morphine and heroin are opioids derived from the latex of the opium poppy plant (Papaver somniferum).', difficulty: 'medium' },
  { id: 'hhd-130', type: 'mcq', question: 'Heroin (diacetylmorphine), a highly addictive opioid drug, is typically taken by:', options: ['Injection, sniffing or smoking', 'Only through eating whole leaves', 'Only through vaccination-style injection of proteins', 'It cannot be administered by any method'], correctIndex: 0, explanation: 'Heroin, commonly called "smack", is a white/grey substance that is typically administered by injection, sniffing or smoking.', difficulty: 'medium' },
  { id: 'hhd-131', type: 'mcq', question: 'Cannabinoids, another class of commonly abused psychoactive drugs, are obtained from the plant:', options: ['Cannabis sativa', 'Papaver somniferum', 'Erythroxylum coca', 'Datura'], correctIndex: 0, explanation: 'Cannabinoids are chemicals obtained from the inflorescence of the plant Cannabis sativa.', difficulty: 'medium' },
  { id: 'hhd-132', type: 'mcq', question: 'Common examples of cannabinoid substances derived from Cannabis sativa include:', options: ['Marijuana, hashish, charas and ganja', 'Cocaine and crack', 'Morphine and heroin', 'LSD and amphetamines'], correctIndex: 0, explanation: 'Marijuana, hashish, charas and ganja are all forms of cannabinoids derived from the Cannabis sativa plant.', difficulty: 'medium' },
  { id: 'hhd-133', type: 'mcq', question: 'Cannabinoids are commonly consumed by which methods?', options: ['Smoking or oral administration', 'Only through skin injection', 'Only through inhalation of vapours from heating metal', 'They cannot be consumed in any way'], correctIndex: 0, explanation: 'Cannabinoids are commonly smoked or taken orally.', difficulty: 'medium' },
  { id: 'hhd-134', type: 'mcq', question: 'Cannabinoids, when consumed, primarily interact with specific receptors present mainly in the:', options: ['Brain', 'Kidneys', 'Skin', 'Lungs exclusively, with no effect elsewhere'], correctIndex: 0, explanation: 'Cannabinoids act primarily by binding to cannabinoid receptors present mainly in the brain, affecting the cardiovascular and nervous systems.', difficulty: 'medium' },
  { id: 'hhd-135', type: 'mcq', question: 'Cocaine, another commonly abused psychoactive substance, is obtained from the plant:', options: ['Erythroxylum coca', 'Cannabis sativa', 'Papaver somniferum', 'Atropa belladonna'], correctIndex: 0, explanation: 'Cocaine is extracted from the coca plant, Erythroxylum coca.', difficulty: 'medium' },
  { id: 'hhd-136', type: 'mcq', question: 'Cocaine, commonly called "coke" or "crack", is generally taken by:', options: ['Snorting', 'Injecting drinking water containing snake venom', 'Consuming raw, unprocessed leaves without any processing', 'It cannot be self-administered in any manner'], correctIndex: 0, explanation: 'Cocaine is typically snorted, and this route of administration interferes with the transport of the neurotransmitter dopamine.', difficulty: 'medium' },
  { id: 'hhd-137', type: 'mcq', question: 'Cocaine primarily acts by interfering with the transport of which neurotransmitter?', options: ['Dopamine', 'Acetylcholine exclusively', 'Insulin', 'Haemoglobin'], correctIndex: 0, explanation: 'Cocaine interferes with the transport of the neurotransmitter dopamine, resulting in the drug\'s stimulant effects.', difficulty: 'medium' },
  { id: 'hhd-138', type: 'mcq', question: 'Cocaine typically produces a temporary state of:', options: ['Euphoria and increased energy', 'Complete unconsciousness immediately upon first use', 'No noticeable psychological effect', 'Permanent loss of all senses'], correctIndex: 0, explanation: 'Cocaine users typically experience a temporary feeling of euphoria and increased energy.', difficulty: 'medium' },
  { id: 'hhd-139', type: 'mcq', question: 'Barbiturates and amphetamines, which act as depressants or stimulants of the central nervous system respectively, along with LSD (Lysergic Acid Diethylamide), are classified as:', options: ['Psychotropic drugs', 'Antibiotics', 'Antihistamines only', 'Antitoxins'], correctIndex: 0, explanation: 'Barbiturates, amphetamines and LSD are examples of psychotropic drugs, affecting mood, perception and behaviour.', difficulty: 'medium' },
  { id: 'hhd-140', type: 'mcq', question: 'Along with drugs, the excessive use of alcohol is also considered a form of substance abuse, primarily affecting which organs upon chronic use?', options: ['Liver and other organs, potentially leading to conditions like cirrhosis', 'Only the skin, with no internal effects', 'Only the eyes', 'Only the hair'], correctIndex: 0, explanation: 'Chronic and excessive alcohol consumption can lead to serious organ damage, particularly affecting the liver, potentially leading to conditions such as cirrhosis.', difficulty: 'medium' },
  { id: 'hhd-141', type: 'assertion', question: 'Assertion (A): Individuals abusing drugs often need increasing doses to achieve the same effect over time.\nReason (R): Repeated drug use can lead to tolerance, whereby the body\'s response to a given dose diminishes, requiring escalating amounts to achieve the desired effect.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The phenomenon of tolerance correctly explains why individuals abusing drugs may require progressively higher doses over time.', difficulty: 'medium' },
  { id: 'hhd-142', type: 'assertion', question: 'Assertion (A): Withdrawal symptoms often occur when a habitual drug user suddenly stops taking the drug.\nReason (R): The body, having adapted to the regular presence of the drug, experiences physiological disturbances when the substance is abruptly withdrawn, a state termed drug dependence.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The concept of physiological dependence correctly explains why sudden cessation of a habitually used drug can trigger withdrawal symptoms.', difficulty: 'medium' },
  { id: 'hhd-143', type: 'count', question: 'Consider the following statements about commonly abused drugs:\n1. Morphine and heroin are opioids obtained from the opium poppy plant.\n2. Cannabinoids are obtained from Cannabis sativa.\n3. Cocaine is obtained from Erythroxylum coca and interferes with dopamine transport.\n4. LSD is classified as an opioid, not a psychotropic drug.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — LSD is a psychotropic drug, not an opioid.', difficulty: 'medium' },
  { id: 'hhd-144', type: 'count', question: 'Consider the following drug-plant source pairs:\n1. Morphine — Papaver somniferum\n2. Cocaine — Erythroxylum coca\n3. Marijuana — Cannabis sativa\n4. Heroin — Erythroxylum coca\nHow many of the above pairs are correctly matched?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Pairs 1, 2 and 3 are correctly matched. Pair 4 is incorrect — heroin is derived from Papaver somniferum (opium poppy), not Erythroxylum coca.', difficulty: 'medium' },
  { id: 'hhd-145', type: 'matching', question: 'Match Column I (drug) with Column II (plant source):\nColumn I: A. Morphine  B. Cocaine  C. Marijuana\nColumn II: i. Erythroxylum coca  ii. Cannabis sativa  iii. Papaver somniferum', options: ['A-iii, B-i, C-ii', 'A-i, B-ii, C-iii', 'A-ii, B-iii, C-i', 'A-iii, B-ii, C-i'], correctIndex: 0, explanation: 'Morphine — Papaver somniferum; Cocaine — Erythroxylum coca; Marijuana — Cannabis sativa.', difficulty: 'medium' },
  { id: 'hhd-146', type: 'statement', question: 'Statement I: Drug tolerance and drug dependence are the same phenomenon.\nStatement II: Tolerance refers to needing increasing doses for the same effect, while dependence refers to the body\'s reliance on the drug, leading to withdrawal symptoms upon discontinuation.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 3, explanation: 'Statement I is incorrect — tolerance and dependence are related but distinct concepts. Statement II correctly distinguishes between the two.', difficulty: 'medium' },

  // ============ ADOLESCENCE AND DRUG/ALCOHOL ABUSE: EFFECTS AND PREVENTION ============
  { id: 'hhd-147', type: 'mcq', question: 'Adolescence is often considered a particularly vulnerable period for the onset of drug and alcohol abuse mainly because it is a period of:', options: ['Significant physical, psychological and emotional changes and general vulnerability to external influences', 'Complete physical and mental stability, with no susceptibility to any external factors', 'Only physical growth, unrelated to psychological factors', 'Immunity from social and peer pressure'], correctIndex: 0, explanation: 'Adolescence is a period of significant physical and psychological change, making young people particularly susceptible to external pressures, including drug and alcohol use.', difficulty: 'medium' },
  { id: 'hhd-148', type: 'mcq', question: 'Common factors that may lead adolescents towards drug and alcohol abuse include:', options: ['Curiosity, need for adventure and thrill, peer pressure, and stress or excessive academic pressure', 'Only genetic predisposition, with no environmental or social factors involved', 'Only complete social isolation, with no peer influence', 'None of these factors have any documented influence'], correctIndex: 0, explanation: 'Various factors — curiosity, thrill-seeking, peer pressure, stress, and unstable family or social conditions — can contribute to drug and alcohol abuse in adolescents.', difficulty: 'medium' },
  { id: 'hhd-149', type: 'mcq', question: 'Prolonged use of drugs or alcohol can have serious negative consequences, including:', options: ['Adverse effects on general health, along with reckless behaviour, violence and disrupted relationships with family and friends', 'Only physical fitness improvement, with no negative consequences', 'Complete resistance to all diseases', 'Improved academic performance in every case'], correctIndex: 0, explanation: 'Drug and alcohol abuse is associated with a range of negative health, behavioural and social consequences, including violence, disrupted relationships, and health complications.', difficulty: 'medium' },
  { id: 'hhd-150', type: 'mcq', question: 'Consumption of alcohol and drugs by pregnant women can have severe consequences for the:', options: ['Baby, causing physiological or psychological harm', 'Only the mother, with no risk to the developing baby', 'Neither the mother nor the baby, since drugs do not cross the placenta', 'Only the father, unrelated to the pregnancy'], correctIndex: 0, explanation: 'Alcohol and drug use during pregnancy can cross the placenta and negatively affect the developing baby, causing physiological or psychological harm.', difficulty: 'medium' },
  { id: 'hhd-151', type: 'mcq', question: 'Excessive doses of drugs may lead to a life-threatening condition known as:', options: ['Overdose, which can cause coma and even death', 'Complete cure of the addiction', 'Immediate improvement of physical fitness', 'Permanent enhancement of memory'], correctIndex: 0, explanation: 'An excessive dose of a drug, especially in cases of addiction with escalating tolerance, can lead to overdose, which can cause coma and death.', difficulty: 'medium' },
  { id: 'hhd-152', type: 'mcq', question: 'Sharing of needles/syringes among drug abusers, particularly for injecting drugs, increases the risk of transmitting which infectious agents?', options: ['HIV and Hepatitis B, among other blood-borne pathogens', 'Only fungal infections, with no risk of viral transmission', 'Only helminthic infections', 'No infections can be transmitted through needle sharing'], correctIndex: 0, explanation: 'Sharing of needles among drug abusers increases the risk of blood-borne infections, notably HIV and Hepatitis B.', difficulty: 'medium' },
  { id: 'hhd-153', type: 'mcq', question: 'Effective prevention and control of drug and alcohol abuse, especially among adolescents, generally requires:', options: ['A combination of avoiding peer pressure, educational and vocational counselling, seeking help from parents/guardians, and looking for medical/professional support when needed', 'Complete social isolation, with no support system', 'Only punitive legal action, without counselling or education', 'Ignoring the issue entirely, expecting it to resolve on its own'], correctIndex: 0, explanation: 'A comprehensive approach — including resisting peer pressure, education, family support, and seeking professional help — is important for the prevention and management of drug and alcohol abuse.', difficulty: 'medium' },
  { id: 'hhd-154', type: 'assertion', question: 'Assertion (A): Adolescents are considered a high-risk group for the onset of drug and alcohol abuse.\nReason (R): Adolescence involves significant physical, hormonal and psychological transitions, along with heightened susceptibility to peer pressure and curiosity-driven experimentation.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The combination of developmental transitions and social vulnerabilities during adolescence correctly explains the increased risk for substance abuse initiation during this period.', difficulty: 'medium' },
  { id: 'hhd-155', type: 'count', question: 'Consider the following statements about the effects of drug and alcohol abuse:\n1. Chronic alcohol abuse can damage the liver.\n2. Drug use during pregnancy poses no risk to the developing baby.\n3. Sharing needles among drug abusers increases the risk of HIV transmission.\n4. Drug overdose can be life-threatening.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is wrong — drug and alcohol use during pregnancy can seriously harm the developing baby.', difficulty: 'medium' },
  { id: 'hhd-156', type: 'statement', question: 'Statement I: Peer pressure is one of several factors that can contribute to drug and alcohol abuse among adolescents.\nStatement II: Educational and vocational counselling, along with family support, can play a role in preventing and managing substance abuse.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements accurately reflect recognised contributing factors and preventive/management strategies related to drug and alcohol abuse.', difficulty: 'easy' },

  // ============ TOBACCO USE ============
  { id: 'hhd-157', type: 'mcq', question: 'Tobacco, commonly consumed through smoking or chewing, contains a highly addictive stimulant compound called:', options: ['Nicotine', 'Caffeine', 'Morphine', 'Cocaine'], correctIndex: 0, explanation: 'Nicotine is the addictive stimulant compound present in tobacco, responsible for the physiological and psychological effects of tobacco use.', difficulty: 'easy' },
  { id: 'hhd-158', type: 'mcq', question: 'Nicotine, when absorbed into the bloodstream through tobacco use, stimulates the adrenal gland to release which hormones?', options: ['Adrenaline and noradrenaline', 'Insulin and glucagon', 'Thyroxine only', 'Growth hormone only'], correctIndex: 0, explanation: 'Nicotine stimulates the adrenal gland to release adrenaline and noradrenaline into the bloodstream, causing an increase in blood pressure and heart rate.', difficulty: 'medium' },
  { id: 'hhd-159', type: 'mcq', question: 'Chronic tobacco use, whether through smoking or chewing, is strongly associated with an increased risk of which type of disease?', options: ['Cancer, particularly of the lung and oral cavity', 'No increase in any disease risk', 'Only benign, harmless skin conditions', 'Complete immunity to all respiratory diseases'], correctIndex: 0, explanation: 'Chronic tobacco use significantly increases the risk of cancers, especially of the lung (from smoking) and oral cavity (from chewing tobacco).', difficulty: 'medium' },
  { id: 'hhd-160', type: 'mcq', question: 'In addition to cancer, chronic smoking is strongly associated with an increased risk of:', options: ['Bronchitis, emphysema, and cardiovascular disorders', 'No additional health risks beyond cancer', 'Only improved lung capacity', 'Only benefits to the cardiovascular system'], correctIndex: 0, explanation: 'Smoking is a major risk factor for bronchitis, emphysema, and various cardiovascular disorders, in addition to cancer.', difficulty: 'medium' },
  { id: 'hhd-161', type: 'mcq', question: 'Carbon monoxide present in cigarette smoke reduces the oxygen-carrying capacity of the blood by binding preferentially to:', options: ['Haemoglobin, forming carboxyhaemoglobin', 'White blood cells', 'Platelets', 'Plasma proteins exclusively'], correctIndex: 0, explanation: 'Carbon monoxide in cigarette smoke binds to haemoglobin (forming carboxyhaemoglobin) with a much higher affinity than oxygen, reducing the blood\'s oxygen-carrying capacity.', difficulty: 'medium' },
  { id: 'hhd-162', type: 'assertion', question: 'Assertion (A): Smoking is a significant risk factor for cardiovascular disease.\nReason (R): Nicotine-induced release of adrenaline and noradrenaline raises blood pressure and heart rate, while carbon monoxide reduces the oxygen-carrying capacity of blood, together straining the cardiovascular system.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The combined physiological effects of nicotine and carbon monoxide correctly explain the increased cardiovascular disease risk associated with smoking, as stated in the assertion.', difficulty: 'medium' },
  { id: 'hhd-163', type: 'count', question: 'Consider the following statements about tobacco use:\n1. Nicotine is the addictive stimulant compound in tobacco.\n2. Nicotine stimulates adrenaline and noradrenaline release, increasing heart rate and blood pressure.\n3. Carbon monoxide in cigarette smoke has a higher affinity for haemoglobin than oxygen.\n4. Chronic tobacco use has no association with cancer risk.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — chronic tobacco use is strongly associated with increased cancer risk.', difficulty: 'medium' },

  // ============ MIXED / REVISION ============
  { id: 'hhd-164', type: 'mcq', question: 'Which of the following pairs is INCORRECTLY matched (disease and causative agent)?', options: ['Typhoid — Salmonella typhi', 'Malaria — Plasmodium species', 'AIDS — Human Immunodeficiency Virus', 'Ringworm — Entamoeba histolytica'], correctIndex: 3, explanation: 'Ringworm is caused by fungi (Trichophyton, Microsporum, Epidermophyton), not Entamoeba histolytica, which causes amoebiasis.', difficulty: 'medium' },
  { id: 'hhd-165', type: 'mcq', question: 'Which of the following best represents the overall theme of the chapter "Human Health and Disease"?', options: ['A study limited only to bacterial infections in humans', 'An overview of common diseases, the immune system, cancer, and issues related to drug and alcohol abuse, all in relation to human health', 'A discussion exclusively about plant diseases', 'A purely historical account of medical discoveries, with no biological content'], correctIndex: 1, explanation: 'The chapter comprehensively covers infectious diseases, immunity, cancer, and drug/alcohol abuse, all central themes relating to human health.', difficulty: 'easy' },
  { id: 'hhd-166', type: 'assertion', question: 'Assertion (A): A strong, well-functioning immune system is important not only for fighting infectious diseases but also plays a role in cancer surveillance.\nReason (R): Components of the immune system, including certain T-lymphocytes, can recognise and eliminate abnormal or cancerous cells before they proliferate into a detectable tumour.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The immune system\'s capacity to detect and eliminate abnormal cells correctly explains its broader role in cancer surveillance, beyond just infectious disease defence.', difficulty: 'medium' },
  { id: 'hhd-167', type: 'count', question: 'Consider the following statements summarising the chapter:\n1. Infectious diseases can be caused by bacteria, viruses, fungi, protozoans and helminths.\n2. Immunity is broadly classified into innate and acquired types.\n3. Cancer is always caused directly by an infectious pathogen, with no other possible causes.\n4. Drug and alcohol abuse can have serious physical, psychological and social consequences.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — cancer can be caused by physical, chemical or biological carcinogens, not only infectious pathogens.', difficulty: 'medium' },
  { id: 'hhd-168', type: 'statement', question: 'Statement I: Prevention strategies for infectious diseases, cancer, and drug/alcohol abuse all involve some combination of awareness, lifestyle choices, and, where applicable, medical intervention.\nStatement II: The specific causative factors and mechanisms differ substantially between infectious diseases, cancer, and substance abuse.\nIn light of the above statements, choose the most appropriate answer:', options: ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'], correctIndex: 0, explanation: 'Both statements are accurate — while general awareness and lifestyle/medical strategies are broadly relevant, the underlying causes and biological mechanisms differ across these distinct health topics.', difficulty: 'medium' },
];
